package cn.qingxing.reminder;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;
public final class ReminderTests extends Instrumentation {
 Context c;int n;void check(boolean b,String m){n++;if(!b)throw new AssertionError(m);}void main(Runnable r){Throwable[] e={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){e[0]=t;}});if(e[0]!=null)throw new AssertionError(e[0]);}
 Notification notice(){for(android.service.notification.StatusBarNotification s:c.getSystemService(NotificationManager.class).getActiveNotifications())if(s.getId()==Alerts.id("pm"))return s.getNotification();return null;}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();c=getTargetContext();try{
 main(()->{Store s=new Store(c);FlowTests.window(s,"pm");Alerts.channels(c);FlowTests.sample(c,false);check(s.pending().length()==0,"initial silence");FlowTests.ready(s);FlowTests.sample(c,false);});Thread.sleep(300);
 Notification first=notice();check(first!=null,"minute node posts actual notification");check((first.flags&Notification.FLAG_INSISTENT)==0,"no looping sound or vibration flag");check(first.actions.length==1&&"已打卡".contentEquals(first.actions[0].title),"only confirmation action; no snooze");NotificationChannel channel=c.getSystemService(NotificationManager.class).getNotificationChannel(Alerts.REMIND);check(channel.getVibrationPattern().length==2&&channel.getVibrationPattern()[1]==400,"one vibration pulse configured");
 main(()->{Store s=new Store(c);long due=s.pending().optJSONObject("pm").optLong("due");FlowTests.sample(c,false);check(due==s.pending().optJSONObject("pm").optLong("due"),"poll does not re-alert between minute nodes");FlowTests.sample(c,true);});Thread.sleep(200);check(notice()==null,"reconnection cancels current notification and sound");
 main(()->{Store s=new Store(c);FlowTests.ready(s);FlowTests.sample(c,false);new AlarmReceiver().onReceive(c,new Intent("SNOOZE").putExtra("key","pm"));check(s.pending().has("pm"),"retired snooze cannot change schedule");});Thread.sleep(200);Notification done=notice();done.actions[0].actionIntent.send();Thread.sleep(300);check(new Store(c).day().optBoolean("pmDone")&&notice()==null,"actual notification action confirms and cancels");
 main(()->{Planner.attendanceUndo(c,"pm");check(new Store(c).pending().length()==0,"undo never restores old repeating notification");});Thread.sleep(200);check(notice()==null,"fresh round waits full minute");
 main(()->{Store s=new Store(c);long origin=s.round().optLong("startedAt");s.prefs.edit().putBoolean("monitorLoud",true).putBoolean("remindLoud",false).commit();Planner.rebuild(c);check(s.round().optLong("startedAt")==origin,"legacy profiles do not reset minute round");Notification monitor=Alerts.monitoring(c,"检查1");check(Alerts.MONITOR.equals(monitor.getChannelId())&&(monitor.flags&Notification.FLAG_ONLY_ALERT_ONCE)!=0,"monitor remains quiet despite old loud choice");FlowTests.ready(s);FlowTests.sample(c,false);});Thread.sleep(200);check(Alerts.REMIND.equals(notice().getChannelId()),"reminder remains noisy despite old quiet choice");

 main(()->{NotificationChannel quiet=new NotificationChannel("test_quiet","test",NotificationManager.IMPORTANCE_LOW);quiet.setSound(null,null);quiet.enableVibration(false);check(Alerts.mismatch(quiet,true,false,false).isEmpty(),"quiet defaults match");check(Alerts.mismatch(quiet,true,true,false).contains("声音未开启")&&Alerts.mismatch(quiet,true,true,false).contains("振动未开启"),"noisy mode diagnoses each disabled cue");quiet.enableVibration(true);check(Alerts.mismatch(quiet,true,false,false).contains("振动应关闭"),"quiet mode diagnoses unexpected vibration");check(Alerts.mismatch(quiet,true,false,true).contains("声音应关闭"),"quiet mode diagnoses unexpected sound");check(Alerts.mismatch(quiet,false,false,false).contains("通知被禁用"),"blocked notification diagnosed");Store s=new Store(c);s.prefs.edit().putBoolean("remindLoud",true).putBoolean("autostartConfirmed",false).commit();Planner.rebuild(c);MonitorService.reconcile(c,true);check(s.pending().length()==0&&s.round().length()==0&&Planner.activeKey(s).isEmpty(),"revoking necessary authorization stops pending and timer");s.prefs.edit().putBoolean("autostartConfirmed",true).commit();Planner.rebuild(c);check(s.round().optLong("nextAt")>=System.currentTimeMillis()+59000,"restoring authorization starts fresh minute");});
 out.putString("stream","PASS "+n+" bounded reminder lifecycle checks: fixed quiet monitoring, bounded 5 second reminder, no snooze");finish(-1,out);
 }catch(Throwable t){out.putString("stream","FAIL "+android.util.Log.getStackTraceString(t));finish(0,out);}finally{main(()->{new Store(c).enabled(false);c.stopService(new Intent(c,MonitorService.class));Planner.reset(c);Planner.rebuild(c);});}}
}
